async function saveHorseHistory(atId,data){if(!rootDir)return false;let p=await rootDir.queryPermission({mode:'readwrite'});if(p!=='granted')p=await rootDir.requestPermission({mode:'readwrite'});if(p!=='granted')return false;let d=await rootDir.getDirectoryHandle('At Yarış İndeksi',{create:true}),fh=await d.getFileHandle(String(atId)+'.json',{create:true}),w=await fh.createWritable();await w.write(JSON.stringify({version:'AT-HISTORY-LOCAL-V1',savedAt:new Date().toISOString(),atId:String(atId),data},null,2));await w.close();return true}
